#!/bin/bash
set -e

dirpath="$(cd "$(dirname "$0")" && pwd)"
# cd "${dirpath}"

# for cert generation
sm_cert_conf='sm_cert.cnf'
# the validity period of the certificate
days=36500
# rsa key length
rsa_key_length=2048

sm_mode='false'
sm2_params="sm_sm2.param"

fisco_path="${HOME}/.fisco"
tassl_path="${fisco_path}/tassl-1.1.1b"
calculate_address="${fisco_path}/calculate_address"
keccak_256_bin="${fisco_path}/keccak-256sum"
keccak_256_tar="${fisco_path}/keccak-256sum.tgz"
sm3_bin="${fisco_path}/sm3"
sm3_tar="${fisco_path}/sm3.tgz"
OPENSSL_CMD="${fisco_path}/tassl-1.1.1b"

# params for command
ca_cert_path=""
output_dir="cert"
account_output_dir="accounts"
sub_command=""
input_params=''
ip_param=""

# for modifying multipy ca node
modify_node_path=""
multi_ca_path=""
sub_cmd_param=''
force_aarch64=""
account_address=""

LOG_WARN() {
    local content=${1}
    echo -e "\033[31m[ERROR] ${content}\033[0m"
}

LOG_INFO() {
    local content=${1}
    echo -e "\033[32m[INFO] ${content}\033[0m"
}

LOG_FALT() {
    local content=${1}
    echo -e "\033[31m[FALT] ${content}\033[0m"
    exit 1
}

dir_must_exists() {
    if [[ ! -d "$1" ]]; then
        LOG_FALT "$1 DIR does not exist, please check!"
    fi
}

dir_must_not_exists() {
    if [[  -d "$1" ]]; then
        LOG_FALT "$1 DIR already exist, please check!"
    fi
}

file_must_not_exists() {
    if [[ -f "$1" ]]; then
        LOG_FALT "$1 file already exist, please check!"
    fi
}

file_must_exists() {
    if [[ ! -f "$1" ]]; then
        LOG_FALT "$1 file does not exist, please check!"
    fi
}

check_name() {
    local name="$1"
    local value="$2"
    [[ "$value" =~ ^[a-zA-Z0-9._-]+$ ]] || {
        LOG_FALT "$name name [$value] invalid, it should match regex: ^[a-zA-Z0-9._-]+\$"
    }
}

generate_random_num(){
    num=`${OPENSSL_CMD} rand -hex 4`
    echo $num
}
randNum=$(generate_random_num)

generate_sm_sm2_param() {
    local output=$1
    cat <<EOF >"${output}"
-----BEGIN EC PARAMETERS-----
BggqgRzPVQGCLQ==
-----END EC PARAMETERS-----

EOF
}

generate_sm_cert_conf() {
    local output=$1
    cat <<EOF >"${output}"
oid_section		= new_oids

[ new_oids ]
tsa_policy1 = 1.2.3.4.1
tsa_policy2 = 1.2.3.4.5.6
tsa_policy3 = 1.2.3.4.5.7

####################################################################
[ ca ]
default_ca	= CA_default		# The default ca section

####################################################################
[ CA_default ]

dir		= ./demoCA		# Where everything is kept
certs		= $dir/certs		# Where the issued certs are kept
crl_dir		= $dir/crl		# Where the issued crl are kept
database	= $dir/index.txt	# database index file.
#unique_subject	= no			# Set to 'no' to allow creation of
					# several ctificates with same subject.
new_certs_dir	= $dir/newcerts		# default place for new certs.

certificate	= $dir/cacert.pem 	# The CA certificate
serial		= $dir/serial 		# The current serial number
crlnumber	= $dir/crlnumber	# the current crl number
					# must be commented out to leave a V1 CRL
crl		= $dir/crl.pem 		# The current CRL
private_key	= $dir/private/cakey.pem # The private key
RANDFILE	= $dir/private/.rand	# private random number file

x509_extensions	= usr_cert		# The extensions to add to the cert

name_opt 	= ca_default		# Subject Name options
cert_opt 	= ca_default		# Certificate field options

default_days	= 36500			# how long to certify for
default_crl_days= 30			# how long before next CRL
default_md	= default		# use public key default MD
preserve	= no			# keep passed DN ordering

policy		= policy_match

[ policy_match ]
countryName		= match
stateOrProvinceName	= match
organizationName	= match
organizationalUnitName	= optional
commonName		= supplied
emailAddress		= optional

[ policy_anything ]
countryName		= optional
stateOrProvinceName	= optional
localityName		= optional
organizationName	= optional
organizationalUnitName	= optional
commonName		= supplied
emailAddress		= optional

####################################################################
[ req ]
default_bits		= 2048
default_md		= sm3
default_keyfile 	= privkey.pem
distinguished_name	= req_distinguished_name
x509_extensions	= v3_ca	# The extensions to add to the self signed cert

string_mask = utf8only

# req_extensions = v3_req # The extensions to add to a certificate request

[ req_distinguished_name ]
countryName = CN
countryName_default = CN
stateOrProvinceName = State or Province Name (full name)
stateOrProvinceName_default =GuangDong
localityName = Locality Name (eg, city)
localityName_default = ShenZhen
organizationalUnitName = Organizational Unit Name (eg, section)
organizationalUnitName_default = fisco
commonName =  Organizational  commonName (eg, fisco)
commonName_default =  fisco
commonName_max = 64

[ usr_cert ]
basicConstraints=CA:FALSE
nsComment			= "OpenSSL Generated Certificate"

subjectKeyIdentifier=hash
authorityKeyIdentifier=keyid,issuer

[ v3_req ]

# Extensions to add to a certificate request

basicConstraints = CA:FALSE
keyUsage = nonRepudiation, digitalSignature

[ v3enc_req ]

# Extensions to add to a certificate request
basicConstraints = CA:FALSE
keyUsage = keyAgreement, keyEncipherment, dataEncipherment

[ v3_agency_root ]
subjectKeyIdentifier=hash
authorityKeyIdentifier=keyid:always,issuer
basicConstraints = CA:true
keyUsage = cRLSign, keyCertSign

[ v3_ca ]
subjectKeyIdentifier=hash
authorityKeyIdentifier=keyid:always,issuer
basicConstraints = CA:true
keyUsage = cRLSign, keyCertSign

EOF
}

generate_cert_conf() {
    local output=$1
    cat <<EOF >"${output}"
[ca]
default_ca=default_ca
[default_ca]
default_days = 36500
default_md = sha256

[req]
distinguished_name = req_distinguished_name
req_extensions = v3_req
[req_distinguished_name]
countryName = CN
countryName_default = CN
stateOrProvinceName = State or Province Name (full name)
stateOrProvinceName_default =GuangDong
localityName = Locality Name (eg, city)
localityName_default = ShenZhen
organizationalUnitName = Organizational Unit Name (eg, section)
organizationalUnitName_default = FISCO-BCOS
commonName =  Organizational  commonName (eg, FISCO-BCOS)
commonName_default = FISCO-BCOS
commonName_max = 64

[ v3_req ]
basicConstraints = CA:FALSE
keyUsage = nonRepudiation, digitalSignature, keyEncipherment

[ v4_req ]
basicConstraints = CA:FALSE

EOF
}

gen_chain_cert() {

    if [[ ! -f "${cert_conf}" ]]; then
        generate_cert_conf "${cert_conf}"
    fi

    local chaindir="${1}"

    file_must_not_exists "${chaindir}"/ca.key
    file_must_not_exists "${chaindir}"/ca.crt
    file_must_exists "${cert_conf}"

    mkdir -p "$chaindir"
    dir_must_exists "$chaindir"

    ${OPENSSL_CMD} genrsa -out "${chaindir}"/ca.key "${rsa_key_length}"
    ${OPENSSL_CMD} req -new -x509 -days "${days}" -subj "/CN=FISCO-BCOS-${randNum}/O=FISCO-BCOS-${randNum}/OU=chain" -key "${chaindir}"/ca.key -config "${cert_conf}" -out "${chaindir}"/ca.crt
    if [ ! -f "${chaindir}/cert.cnf" ];then
        mv "${cert_conf}" "${chaindir}"
    fi
    LOG_INFO "Build ca cert successfully!"
}

gen_rsa_node_private_and_csr() {
    local ndpath="${1}"
    local type="${2}"

    if [[ ! -f "${cert_conf}" ]]; then
        generate_cert_conf "${cert_conf}"
    fi

    # check_name node "$node"
    file_must_not_exists "$ndpath"/"${type}".key

    mkdir -p "${ndpath}"
    dir_must_exists "${ndpath}"

    ${OPENSSL_CMD} genrsa -out "${ndpath}"/"${type}".key "${rsa_key_length}" 2> /dev/null
    ${OPENSSL_CMD} req -new -sha256 -subj "/CN=FISCO-BCOS-${randNum}/O=fisco-bcos/OU=agency" -key "$ndpath"/"${type}".key -config ${cert_conf} -out "$ndpath"/"${type}".csr

    ${OPENSSL_CMD} pkcs8 -topk8 -in "$ndpath"/"$type".key -out "$ndpath"/pkcs8_node.key -nocrypt

    rm -f "$ndpath"/"${type}".key
    mv "$ndpath"/pkcs8_node.key "$ndpath"/"${type}".key
    cp "${cert_conf}" "$ndpath"

    # extract p2p id
    ${OPENSSL_CMD} rsa -in "$ndpath"/"$type".key -pubout -out public.pem
    ${OPENSSL_CMD} rsa -pubin -in public.pem -text -noout 2> /dev/null | sed -n '3,20p' | sed 's/://g' | tr "\n" " " | sed 's/ //g' | awk '{print substr($0,3);}'  | cat > "${ndpath}/${type}.nodeid"
    rm -f public.pem

    LOG_INFO "Build rsa node cert private with csr successful!"
}

sign_rsa_node_cert_private_csr() {
    local capath="${1}"
    local csrpath="${2}"
    local type="${3}"

    # check_name node "$node"
    file_must_exists "${csrpath}"

    file_must_exists "$capath/ca.key"
    file_must_exists "$capath/ca.crt"
    file_must_exists "$capath/cert.cnf"

    local output=$(dirname ${csrpath})

    mkdir -p "${output}"
    dir_must_exists "${output}"

    ${OPENSSL_CMD} x509 -req -days "${days}" -sha256 -CA "${capath}"/ca.crt -CAkey "$capath"/ca.key -CAcreateserial \
        -in "${csrpath}" -out "$output"/"${type}".crt -extensions v4_req -extfile "$capath"/cert.cnf 2>/dev/null

    cp "$capath"/ca.crt "$capath"/cert.cnf "$output"

    LOG_INFO "Sign rsa node cert private with csr successful!"
}

gen_rsa_node_cert() {
    local capath="${1}"
    local ndpath="${2}"
    local type="${3}"

    file_must_exists "$capath/ca.key"
    file_must_exists "$capath/ca.crt"
    # check_name node "$node"

    file_must_not_exists "$ndpath"/"${type}".key
    file_must_not_exists "$ndpath"/"${type}".crt

    mkdir -p "${ndpath}"
    dir_must_exists "${ndpath}"

    ${OPENSSL_CMD} genrsa -out "${ndpath}"/"${type}".key "${rsa_key_length}" 2> /dev/null
    ${OPENSSL_CMD} req -new -sha256 -subj "/CN=FISCO-BCOS-${randNum}/O=fisco-bcos/OU=agency" -key "$ndpath"/"${type}".key -config "$capath"/cert.cnf -out "$ndpath"/"${type}".csr
    ${OPENSSL_CMD} x509 -req -days "${days}" -sha256 -CA "${capath}"/ca.crt -CAkey "$capath"/ca.key -CAcreateserial \
        -in "$ndpath"/"${type}".csr -out "$ndpath"/"${type}".crt -extensions v4_req -extfile "$capath"/cert.cnf 2>/dev/null

    ${OPENSSL_CMD} pkcs8 -topk8 -in "$ndpath"/"$type".key -out "$ndpath"/pkcs8_node.key -nocrypt
    cp "$capath"/ca.crt "$capath"/cert.cnf "$ndpath"/

    rm -f "$ndpath"/"${type}".csr
    rm -f "$ndpath"/"${type}".key

    mv "$ndpath"/pkcs8_node.key "$ndpath"/"${type}".key

    # extract p2p id
    ${OPENSSL_CMD} rsa -in "$ndpath"/"$type".key -pubout -out public.pem
    ${OPENSSL_CMD} rsa -pubin -in public.pem -text -noout 2> /dev/null | sed -n '3,20p' | sed 's/://g' | tr "\n" " " | sed 's/ //g' | awk '{print substr($0,3);}'  | cat > "${ndpath}/${type}.nodeid"
    rm -f public.pem

    LOG_INFO "Build node cert successful!"
}

gen_sm_chain_cert() {
    local chaindir="${1}"
    name=$(basename "$chaindir")
    check_name chain "$name"

    mkdir -p "$chaindir"
    dir_must_exists "$chaindir"

    "$OPENSSL_CMD" genpkey -paramfile "${sm2_params}" -out "$chaindir/sm_ca.key"
    "$OPENSSL_CMD" req -config sm_cert.cnf -x509 -days "${days}" -subj "/CN=FISCO-BCOS-${randNum}/O=FISCO-BCOS-${randNum}/OU=chain" -key "$chaindir/sm_ca.key" -extensions v3_ca -out "$chaindir/sm_ca.crt"
    if [ ! -f "${chaindir}/${sm_cert_conf}" ];then
        cp "${sm_cert_conf}" "${chaindir}"
    fi
    if [[ ! -f "${chaindir}/${sm2_params}" ]];then
        cp "${sm2_params}" "${chaindir}"
    fi
}

gen_sm_node_private_and_csr() {
    local ndpath="${1}"
    local type="${2}"

    file_must_not_exists "$ndpath/sm_${type}.csr"
    file_must_not_exists "$ndpath/sm_${type}.key"

    mkdir -p "$ndpath"

    "$OPENSSL_CMD" genpkey -paramfile "${sm2_params}" -out "$ndpath/sm_${type}.key"
    "$OPENSSL_CMD" req -new -subj "/CN=FISCO-BCOS-${randNum}/O=fisco-bcos/OU=${type}" -key "$ndpath/sm_${type}.key" -config "${sm_cert_conf}" -out "$ndpath/sm_${type}.csr"

    # nodeid is pubkey
    "$OPENSSL_CMD" ec -in "$ndpath/sm_${type}.key" -text -noout 2> /dev/null | sed -n '7,11p' | sed 's/://g' | tr "\n" " " | sed 's/ //g' | awk '{print substr($0,3);}' | cat > "$ndpath/sm_${type}.nodeid"
}

sign_sm_node_private_and_csr() {
    local capath="$1"
    local ndpath="$2"
    local type="$3"
    local extensions="$4"

    file_must_exists "$capath/sm_ca.key"
    file_must_exists "$capath/sm_ca.crt"
    # file_must_exists "$ndpath/sm_${type}.key"
    file_must_exists "$ndpath/sm_${type}.csr"

    file_must_not_exists "$ndpath/sm_${type}.crt"

    echo "use $(basename "$capath") to sign $(basename $ndpath) ${type}"
    "$OPENSSL_CMD" x509 -sm3 -req -CA "$capath/sm_ca.crt" -CAkey "$capath/sm_ca.key" -days "${days}" -CAcreateserial -in "$ndpath/sm_${type}.csr" -out "$ndpath/sm_${type}.crt" -extfile "$capath/sm_cert.cnf" -extensions "$extensions"
    cp "$capath/sm_ca.crt" "$ndpath"
}

gen_sm_node_cert_with_ext() {
    local capath="$1"
    local certpath="$2"
    local type="$3"
    local extensions="$4"

    file_must_exists "$capath/sm_ca.key"
    file_must_exists "$capath/sm_ca.crt"

    file_must_not_exists "$ndpath/sm_${type}.crt"
    file_must_not_exists "$ndpath/sm_${type}.key"

    "$OPENSSL_CMD" genpkey -paramfile "$capath/${sm2_params}" -out "$certpath/sm_${type}.key"
    "$OPENSSL_CMD" req -new -subj "/CN=FISCO-BCOS-${randNum}/O=fisco-bcos/OU=${type}" -key "$certpath/sm_${type}.key" -config "$capath/sm_cert.cnf" -out "$certpath/sm_${type}.csr"

    echo "use $(basename "$capath") to sign $(basename $certpath) ${type}"
    "$OPENSSL_CMD" x509 -sm3 -req -CA "$capath/sm_ca.crt" -CAkey "$capath/sm_ca.key" -days "${days}" -CAcreateserial -in "$certpath/sm_${type}.csr" -out "$certpath/sm_${type}.crt" -extfile "$capath/sm_cert.cnf" -extensions "$extensions"

    #nodeid is pubkey
    "$OPENSSL_CMD" ec -in "$ndpath/sm_${type}.key" -text -noout 2> /dev/null | sed -n '7,11p' | sed 's/://g' | tr "\n" " " | sed 's/ //g' | awk '{print substr($0,3);}' | cat > "$ndpath/sm_${type}.nodeid"

    rm -f "$certpath/sm_${type}.csr"
}

generate_multi_nodes_cert_impl()
{
    local capath="${1}"
    local type="${2}"
    local output="${3}"

    if [[ -z ${ip_params}  ]];then
        LOG_FALT "ip param is empty, please use \'-l\' command to set ip param."
    fi

    local ip_array=(${ip_params//,/ })
    # check params
    for line in ${ip_array[*]}; do
        ip=${line%:*}
        num=${line#*:}

        # check ip format
        if [[ -z $(echo ${ip} | grep -E "^[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}$") ]]; then
            LOG_FALT "Invalid ip address, please check the IP address: ${ip}"
        fi
    done

    # generate rsa node cert for every server
    for line in ${ip_array[*]}; do
        ip=${line%:*}
        num=${line#*:}

        for ((i = 0; i < num; ++i)); do
            if [[ "${sm_mode}" == "false" ]]; then
                gen_rsa_node_cert "${capath}" "${output}/${ip}_${i}/" "${type}"
            else
                gen_sm_node_cert "${capath}" "${output}/${ip}_${i}/" "${type}"
            fi
        done
    done

}

generate_multi_nodes_private_key_impl()
{
    local output="${1}"
    local nodeids_dir="${output}/nodeids"

    if [[ -z ${ip_params}  ]];then
        LOG_FALT "ip param is empty, please use \'-l\' command to set ip param."
    fi

    local ip_array=(${ip_params//,/ })
    # check params
    for line in ${ip_array[*]}; do
        ip=${line%:*}
        num=${line#*:}

        # check ip format
        if [[ -z $(echo ${ip} | grep -E "^[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}$") ]]; then
            LOG_FALT "Invalid ip address, please check the IP address: ${ip}"
        fi
    done

    mkdir -p "${nodeids_dir}"

    # generate rsa node cert for every server
    for line in ${ip_array[*]}; do
        ip=${line%:*}
        num=${line#*:}

        for ((i = 0; i < num; ++i)); do
            if [[ "${sm_mode}" == "false" ]]; then
                generate_private_key "${output}/${ip}_${i}/"
            else
                generate_sm_private_key "${output}/${ip}_${i}/"
            fi

            file_must_exists "${output}/${ip}_${i}/node.nodeid"
            cp "${output}/${ip}_${i}/node.nodeid" "${nodeids_dir}/${ip}_${i}.nodeid"
        done
    done

}

gen_sm_node_cert() {
    local capath="${1}"
    local ndpath="${2}"
    local type="${3}"

    file_must_exists "$capath/sm_ca.key"
    file_must_exists "$capath/sm_ca.crt"

    mkdir -p "$ndpath"
    dir_must_exists "$ndpath"
    local node=$(basename "$ndpath")
    check_name node "$node"

    gen_sm_node_cert_with_ext "$capath" "$ndpath" ${type} v3_req
    gen_sm_node_cert_with_ext "$capath" "$ndpath" "en${type}" v3enc_req
    # nodeid is pubkey
    # $OPENSSL_CMD ec -in "$ndpath/sm_${type}.key" -text -noout 2> /dev/null | sed -n '7,11p' | sed 's/://g' | tr "\n" " " | sed 's/ //g' | awk '{print substr($0,3);}' | cat > "$ndpath/sm_${type}.nodeid"

    cp "$capath/sm_ca.crt" "$ndpath"
}

generate_single_node_cert() {
    local sm_mode="${1}"
    local ca_path="${2}"
    local node_cert_path="${3}"
    local type="${4}"

    mkdir -p ${node_cert_path}
    if [[ "${sm_mode}" == "false" ]]; then
        gen_rsa_node_cert "${ca_path}" "${node_cert_path}" "${type}" 2>&1
    else
        gen_sm_node_cert "${ca_path}" "${node_cert_path}" "${type}" 2>&1
    fi
}

generate_single_node_csr() {
    local sm_mode="${1}"
    local node_path="${2}"
    local type="${3}"

    mkdir -p ${node_path}
    if [[ "${sm_mode}" == "false" ]]; then
        gen_rsa_node_private_and_csr "${node_path}" "${type}" 2>&1
    else
        gen_sm_node_private_and_csr "${node_path}" "${type}" 2>&1
        gen_sm_node_private_and_csr "${node_path}" "en${type}" 2>&1
    fi
}

sign_single_node_csr() {
    local sm_mode="${1}"
    local ca_path="${2}"
    local csr_path="${3}"
    local type="${4}"

    if [[ "${sm_mode}" == "false" ]]; then
        sign_rsa_node_cert_private_csr "${ca_path}" "${csr_path}" "${type}" 2>&1
    else
        sign_sm_node_private_and_csr "${ca_path}" "${csr_path}" "${type}" v3_req
        sign_sm_node_private_and_csr "${ca_path}" "${csr_path}" "en${type}" v3enc_req
    fi
}

generate_chain_cert(){
    local sm_mode="${1}"
    local chain_cert_path="${2}"
    mkdir -p "${chain_cert_path}"
    if [[ "${sm_mode}" == "false" ]]; then
        gen_chain_cert "${chain_cert_path}" 2>&1
    else
        gen_sm_chain_cert "${chain_cert_path}" 2>&1
    fi
}

generate_private_key()
{
    local output_path="${1}"
    if [[ ! -d "${output_path}" ]];then
        mkdir -p ${output_path}
    fi
    if [[ ! -f /tmp/secp256k1.param ]];then
        ${OPENSSL_CMD} ecparam -out /tmp/secp256k1.param -name secp256k1
    fi
    ${OPENSSL_CMD} genpkey -paramfile /tmp/secp256k1.param -out ${output_path}/node.pem
    # generate nodeid
    ${OPENSSL_CMD} ec -text -noout -in "${output_path}/node.pem" 2> /dev/null | sed -n '7,11p' | tr -d ": \n" | awk '{print substr($0,3);}' | cat >"$output_path"/node.nodeid
}

generate_sm_private_key()
{
    local output_path="${1}"
    if [[ ! -d "${output_path}" ]];then
        mkdir -p ${output_path}
    fi

    ${OPENSSL_CMD} genpkey -paramfile ${sm2_params} -out ${output_path}/node.pem 2>/dev/null
    ${OPENSSL_CMD} ec -in "$output_path/node.pem" -text -noout 2> /dev/null | sed -n '7,11p' | sed 's/://g' | tr "\n" " " | sed 's/ //g' | awk '{print substr($0,3);}'  | cat > "$output_path/node.nodeid"
}

generate_account()
{
    local output_path="${1}"
    generate_private_key "${output_path}"

    rm "${output_path}"/node.nodeid
    # calculate address
    calc_account_address "${output_path}/node.pem"
    mv ${output_path}/node.pem ${output_path}/0x${account_address}.pem

    LOG_INFO "Private Key (pem) : ${output_path}/0x${account_address}.pem"
    # echo "0x${privKey}" > ${output_path}/${account_address}.private.hex
    "${OPENSSL_CMD}" ec -in ${output_path}/0x${account_address}.pem -pubout -out ${output_path}/0x${account_address}.pem.pub 2>/dev/null
    LOG_INFO "Public  Key (pem) : ${output_path}/0x${account_address}.pem.pub"
}

generate_sm_account()
{
    local output_path="${1}"
    generate_sm_private_key "${output_path}"

    rm "${output_path}"/node.nodeid
    # calculate address
    calc_sm_account_address "${output_path}/node.pem"
    mv ${output_path}/node.pem ${output_path}/0x${account_address}_sm.pem

    LOG_INFO "Private Key (pem) : ${output_path}/0x${account_address}_sm.pem"
    # echo "0x${privKey}" > ${output_path}/${account_address}.private.hex
    "${OPENSSL_CMD}" ec -in ${output_path}/0x${account_address}_sm.pem -pubout -out ${output_path}/0x${account_address}_sm.pem.pub 2>/dev/null
    LOG_INFO "Public  Key (pem) : ${output_path}/0x${account_address}_sm.pem.pub"
}

calc_account_address()
{
    local pem_file=$1
    local ret_address=$2
    local suffix=${pem_file##*.}
    if [[ "${suffix}" != "pem" ]];then
        echo "The suffix of ${pem_file} is not pem. Please check it."
        exit 1
    fi

    local privKey=$(${OPENSSL_CMD} ec -in ${pem_file} -text -noout 2>/dev/null| sed -n '3,5p' | tr -d ": \n" | awk '{print $0}')
    local pubKey=$(${OPENSSL_CMD} ec -in ${pem_file} -text -noout 2>/dev/null| sed -n '7,11p' | tr -d ": \n" | awk '{print substr($0,3);}')
    if [[ "$(uname -p)" == "aarch64" || ! -z "${force_aarch64}" ]];then
        account_address=$("${calculate_address}" ${pubKey} | tail -c 41)
    else
        account_address=$(echo ${pubKey}| ${keccak_256_bin} -x -l | tr -d ' -' | tail -c 41)
    fi
    LOG_INFO "Account Address   : 0x${account_address}"
}

calc_sm_account_address()
{
    local pem_file="${1}"
    local suffix=${pem_file##*.}
    if [[ "${suffix}" != "pem" ]];then
        echo "The suffix of ${pem_file} is not pem. Please check it."
        exit 1
    fi
    privKey=$(${OPENSSL_CMD} ec -in ${pem_file} -text -noout 2>/dev/null| sed -n '3,5p' | tr -d ": \n" | awk '{print $0}')
    pubKey=$(${OPENSSL_CMD} ec -in ${pem_file} -text -noout 2>/dev/null| sed -n '7,11p' | tr -d ": \n" | awk '{print substr($0,3);}')
    # echo "public key = ${pubKey}"
    account_address=$(${sm3_bin}  ${pubKey})
    LOG_INFO "Account Address   : 0x${account_address}"
}

exit_with_clean()
{
    local content=${1}
    echo -e "\033[31m[ERROR] ${content}\033[0m"
    if [[ -d "${output_dir}" ]];then
        rm -rf ${output_dir}
    fi
    exit 1
}

check_openssl()
{
    local openssl_cmd="${1}"
    local openssl_version="$(${openssl_cmd} version)"
    [[ "${openssl_version}" == *"OpenSSL 1.1"* || "${openssl_version}" == *"OpenSSL 3."* ||
        "${openssl_version}" == *"Tongsuo"* ]] || {
        LOG_FALT "OpenSSL 1.1, OpenSSL 3 or Tongsuo is required; got: ${openssl_version}"
        exit 1
    }
}

prepare_sm3()
{
    mkdir -p "${fisco_path}"
    if [[ ! -f ${sm3_bin} ]];then
        if [[ "$(uname)" == "Darwin" ]];then
            sm3_base64=""
            echo ${sm3_base64} | base64 -d > ${sm3_tar}
        else
            if [[ "$(uname -p)" == "aarch64" || ! -z "${force_aarch64}" ]];then
                sm3_base64=""
            else
                sm3_base64=""
            fi
                echo ${sm3_base64} | base64 -d > ${sm3_tar}
        fi
        tar -zxf ${sm3_tar} -C "${fisco_path}" && rm ${sm3_tar}
        if [[ -f ${sm3_bin} ]];then
            chmod a+rx ${sm3_bin}
        fi
        if [[ "$(uname -p)" == "aarch64" || ! -z "${force_aarch64}" ]];then
            sm3_bin="${fisco_path}/calculate_address -g"
            chmod a+rx "${fisco_path}/calculate_address"
        fi
    fi
}

prepare_keccak256()
{
    mkdir -p "${fisco_path}"
    if [[ ! -f "${keccak_256_bin}" || ! -f "${calculate_address}" ]];then
        if [[ "$(uname)" == "Darwin" ]];then
            keccak256sum=""
            echo ${keccak256sum} | base64 -d > ${keccak_256_tar}
        else
            if [[ "$(uname -p)" == "aarch64" || ! -z "${force_aarch64}" ]];then
                keccak256sum=""
            else
                keccak256sum=""
            fi
            echo ${keccak256sum} | base64 -d > ${keccak_256_tar}
        fi
        tar -zxf ${keccak_256_tar} -C "${fisco_path}" && rm ${keccak_256_tar}
        if [[ -f ${keccak_256_bin} ]];then
            chmod a+rx ${keccak_256_bin}
        fi
    fi
}

prepare_tassl()
{
    if [[ -f "${OPENSSL_CMD}" ]];then
        # LOG_INFO "TASSL has has been installed"
        return
    fi

    # https://en.wikipedia.org/wiki/Uname#Examples
    local x86_64_name="x86_64"
    local arm_name="aarch64"
    local os_name="linux"
    if [[ "$(uname)" == "Darwin" ]];then
        x86_64_name="x86_64"
        arm_name="arm64"
        os_name="macOS"
    fi
    
    local tassl_arch_name="x86_64"
    local platform="$(uname -m)"
    if [[ "${platform}" == "${arm_name}" ]];then
        tassl_arch_name="aarch64"
    elif [[ "${platform}" == "${x86_64_name}" ]];then
        tassl_arch_name="x86_64"
    else
        LOG_FATAL "Unsupported platform ${platform} for ${os_name}"
        exit 1
    fi

    local tassl_tgz_name="tassl-1.1.0.tar.gz"
    mkdir -p "${fisco_path}"

    local tassl_tgz_base64=""
    if [[ "$(uname)" == "Darwin" ]];then
        # mac
        tassl_tgz_base64=""
        echo ${tassl_tgz_base64} | base64 -d > ${tassl_tgz_name}
        tar zxvf ${tassl_tgz_name} && rm ${tassl_tgz_name}
        local mac_tassl_bin_name="tassl-1.1.1b-macOS-x86_64"
        mv "${mac_tassl_bin_name}" "${tassl_path}"
        chmod a+x "${tassl_path}"
    else 
        # linux x64 & arm
        if [[ "$(uname -p)" == "aarch64" || ! -z "${force_aarch64}" ]];then
            tassl_tgz_base64=""
            echo ${tassl_tgz_base64} | base64 -d > ${tassl_tgz_name}
            tar zxvf ${tassl_tgz_name} 2> /dev/null && rm ${tassl_tgz_name}
            local mac_tassl_bin_name="tassl-1.1.1b-linux-aarch64"
            mv "${mac_tassl_bin_name}" "${tassl_path}"
            chmod a+x "${tassl_path}"
        else
             tassl_tgz_base64=""

             echo ${tassl_tgz_base64} | base64 -d > ${tassl_tgz_name}
             tar zxvf ${tassl_tgz_name} 2> /dev/null && rm ${tassl_tgz_name}
             local mac_tassl_bin_name="tassl-1.1.1b-linux-x86_64"
             mv "${mac_tassl_bin_name}" "${tassl_path}"
             chmod a+x "${tassl_path}"
        fi
    fi
}

help() {
    echo $1
    cat <<EOF
Usage:
    -c <commands>                       [Required] the operation sub command support list:
                                                        - generate_all_cert
                                                        - generate_ca_cert
                                                        - generate_node_cert
                                                        - generate_node_csr
                                                        - sign_node_csr
                                                        - generate_sdk_cert
                                                        - generate_sdk_csr
                                                        - sign_sdk_csr
                                                        - generate_private_key
                                                        - get_hsm_nodeid
                                                        - generate_account
                                                        - calc_account_address
    -o <output dir>                     [Optional] output directory default ./cert
    -s <SM model>                       [Optional] SM switch, default no
    -i <Input>                          [Optional] optional input params
    -d <ca cert path>                   [Optional] ca certificate path, specify ca certificate path to generate node/sdk certificate
    -l <IP list>                        [Optional] list of ip for generate certificate or private key, working with generate_node_cert/generate_private_key
    -O <OpenSSL path>                   [Optional] specify an OpenSSL 1.1/3.x or Tongsuo executable, default download TASSL 1.1.1b to local dir ~/.fisco/tassl-1.1.1b
    -n <node path>                      [Optional] set the path of the node modified to multi ca mode
    -m <multi ca path>                  [Optional] set the path of another ca for multi ca mode
    -p <additional params>              [Optional] additional arguments for some command
    -h Help
EOF
    exit 0
}

parse_params() {
    while getopts "ap:o:O:d:c:sl:hn:m:" option; do
        case $option in
        a) force_aarch64="true" ;;
        c) sub_command="$OPTARG";;
        d) 
            ca_cert_path="$OPTARG"
            dir_must_exists "${ca_cert_path}"
            ;;
        o)
            output_dir="$OPTARG"
            mkdir -p "$output_dir"
            dir_must_exists "${output_dir}"

            account_output_dir="$OPTARG"
            ;;
        s) 
            sm_mode="true" 
            if [[ ! -f "${sm2_params}" ]];then
                generate_sm_sm2_param ${sm2_params}
            fi

            if [[ ! -f "${sm_cert_conf}" ]];then
                generate_sm_cert_conf "${sm_cert_conf}"
            fi
        ;;
        p) sub_cmd_param="$OPTARG" ;;
        l) ip_params="$OPTARG" ;;
        O)
            OPENSSL_CMD="$OPTARG"
            check_openssl "${OPENSSL_CMD}"
            LOG_INFO "The OpenSSL path is specified: ${OPENSSL_CMD}"
            ;;
        n)
            modify_node_path=$OPTARG
            dir_must_exists "${modify_node_path}"
            ;;
        m)
            multi_ca_path="$OPTARG"
            local last_char=${multi_ca_path: -1}
            if [ ${last_char} == "/" ]; then
                multi_ca_path=${OPTARG%/*}
            fi
            file_must_exists "${multi_ca_path}"
            ;;
        h) help ;;
        *) help ;;
        esac
    done
}

generate_all_cert(){
    LOG_INFO "generate all cert"
    cert_dir="${output_dir}/ssl"
    sdk_dir="${output_dir}/sdk"
    mkdir -p "$ca_cert_path"
    mkdir -p "$cert_dir"
    mkdir -p "$sdk_dir"
    generate_chain_cert "${sm_mode}" "${ca_cert_path}"
    generate_single_node_cert "${sm_mode}" "${ca_cert_path}" "${cert_dir}" "ssl"
    generate_single_node_cert "${sm_mode}" "${ca_cert_path}" "${sdk_dir}" "sdk"
    LOG_INFO "generate all cert success"
}

generate_ca_cert()
{
    LOG_INFO "generate ca cert"
    mkdir -p "$ca_cert_path"
    generate_chain_cert "${sm_mode}" "${ca_cert_path}"
    LOG_INFO "generate ca cert success"
}

generate_node_csr()
{
    LOG_INFO "generate node csr"
    cert_dir="${output_dir}/ssl"
    mkdir -p "$cert_dir"
    generate_single_node_csr "${sm_mode}" "${cert_dir}" "ssl"
    LOG_INFO "generate node csr success"
}

sign_node_csr()
{
    LOG_INFO "sign node csr"
    local csr_path="${sub_cmd_param}"
    sign_single_node_csr "${sm_mode}" "${ca_cert_path}" "${csr_path}" "ssl"
    LOG_INFO "sign node csr success"
}

generate_node_cert()
{
    LOG_INFO "generate node cert"
    cert_dir="${output_dir}/ssl"
    mkdir -p "$cert_dir"
    generate_single_node_cert "${sm_mode}" "${ca_cert_path}" "${cert_dir}" "ssl"
    LOG_INFO "generate node cert success"
}

generate_multi_nodes_cert()
{
    LOG_INFO "generate multi nodes cert, ip param: ${ip_params}"
    generate_multi_nodes_cert_impl "${ca_cert_path}" "ssl" "${output_dir}"
    LOG_INFO "generate multi nodes cert success"
}

generate_sdk_cert()
{
    LOG_INFO "generate sdk cert"
    sdk_dir="${output_dir}/sdk"
    mkdir -p "$sdk_dir"
    generate_single_node_cert "${sm_mode}" "${ca_cert_path}" "${sdk_dir}" "sdk"
    LOG_INFO "generate node cert success"
}

generate_sdk_csr()
{
    LOG_INFO "generate sdk csr"
    cert_dir="${output_dir}/sdk"
    mkdir -p "$cert_dir"
    generate_single_node_csr "${sm_mode}" "${cert_dir}" "sdk"
    LOG_INFO "generate sdk csr success"
}

sign_sdk_csr()
{
    LOG_INFO "sign sdk csr"
    local csr_path="${sub_cmd_param}"
    sign_single_node_csr "${sm_mode}" "${ca_cert_path}" "${csr_path}" "sdk"
    LOG_INFO "sign sdk csr success"
}

generate_node_private_key()
{
    LOG_INFO "Generate node private key"
    if [[ "${sm_mode}" == "false" ]]; then
        generate_private_key "${output_dir}"
    else
        generate_sm_private_key "${output_dir}"
    fi
    LOG_INFO "Generate node private key success"
}

get_hsm_nodeid_from_pem_file()
{
    LOG_INFO "get hsm nodeid from pem file"
    file_must_exists "${sub_cmd_param}"
    node_id=$(${OPENSSL_CMD} x509 -in "${sub_cmd_param}" -noout -text | grep "pub:" -A5 | grep -v "pub:" | tr -d ": \n")
    stripped_nodeid="${node_id#04}"
    echo "nodeid=${stripped_nodeid}"

}

generate_sdk_account()
{
    LOG_INFO "Generate account"
    if [[ "${sm_mode}" == "false" ]]; then
        generate_account "${account_output_dir}"
    else
        generate_sm_account "${account_output_dir}"
    fi
    LOG_INFO "Generate account success"
}

calculate_acccount_address()
{
    # LOG_INFO "Calculate account"
    local pem_file="${sub_cmd_param}"
    if [[ "${sm_mode}" == "false" ]]; then
        calc_account_address "${pem_file}"
    else
        calc_sm_account_address "${pem_file}"
    fi
    # LOG_INFO "Calculate account success"
}

generate_multi_nodes_private_key()
{
    LOG_INFO "generate multi nodes private key, sm_mode: ${sm_mode}, ip param: ${ip_params}"
    generate_multi_nodes_private_key_impl "${output_dir}"
    LOG_INFO "generate multi nodes private key success"
}

modify_node_ca_setting(){
    dir_must_not_exists "${modify_node_path}/conf/multiCaPath"
    file_must_exists "${multi_ca_path}"
    mkdir ${modify_node_path}/conf/multiCaPath 2>/dev/null
    cp ${multi_ca_path} ${modify_node_path}/conf/multiCaPath/${1}.0 2>/dev/null
    # sed -i "s/; mul_ca_path=multiCaPath/mul_ca_path=multiCaPath/g" ${modify_node_path}/config.ini

    LOG_INFO "Modify node ca setting success"
}

modify_multiple_ca_node(){
    check_and_install_tassl
    subject_hash=`${OPENSSL_CMD} x509 -hash -noout -in ${multi_ca_path} 2>/dev/null`
    if [[ ! "${multi_ca_path}" || ! "${modify_node_path}" ]];then
        LOG_FATAL "multi_ca_path and modify_node_path are required!"
    fi
    modify_node_ca_setting "${subject_hash}"
}

check_and_install_tassl(){
    if [ -f "${OPENSSL_CMD}" ];then
        return
    fi
    # https://en.wikipedia.org/wiki/Uname#Examples
    local x86_64_name="x86_64"
    local arm_name="aarch64"
    local tassl_mid_name="linux"
    if [[ -n "${macOS}" ]];then
        x86_64_name="x86_64"
        arm_name="arm64"
        tassl_mid_name="macOS"
    fi

    local tassl_post_fix="x86_64"
    local platform="$(uname -m)"
    if [[ "${platform}" == "${arm_name}" ]];then
        tassl_post_fix="aarch64"
    elif [[ "${platform}" == "${x86_64_name}" ]];then
        tassl_post_fix="x86_64"
    else
        LOG_FATAL "Unsupported platform ${platform} for ${tassl_mid_name}"
        exit 1
    fi
    local tassl_package_name="tassl-1.1.1b-${tassl_mid_name}-${tassl_post_fix}"
    local tassl_tgz_name="${tassl_package_name}.tar.gz"
    local tassl_link_prefix="${cdn_link_header}/FISCO-BCOS/tools/tassl-1.1.1b/${tassl_tgz_name}"
    LOG_INFO "Downloading tassl binary from ${tassl_link_prefix}..."
    wget --no-check-certificate  "${tassl_link_prefix}"
    tar zxvf ${tassl_tgz_name} && rm ${tassl_tgz_name}
    chmod u+x ${tassl_package_name}
    mkdir -p "${HOME}"/.fisco
    mv ${tassl_package_name} "${HOME}"/.fisco/tassl-1.1.1b
}

main() {
    parse_params "$@"
    prepare_tassl
    prepare_keccak256
    prepare_sm3
    cert_conf="${output_dir}/cert.cnf"
    if [[ -z "${ca_cert_path}" ]];then
        ca_cert_path="${output_dir}/ca"
    fi
    if [[ "${sub_command}" == "generate_all_cert" ]]; then
        generate_all_cert
    elif [[ "${sub_command}" == "generate_ca_cert" ]]; then
        generate_ca_cert
    elif [[ "${sub_command}" == "generate_node_cert" ]]; then
        if [[ -z ${ip_params} ]];then
            generate_node_cert
        else 
            generate_multi_nodes_cert
        fi
    elif [[ "${sub_command}" == "generate_node_csr" ]]; then
        generate_node_csr
    elif [[ "${sub_command}" == "sign_node_csr" ]]; then
        sign_node_csr
    elif [[ "${sub_command}" == "generate_sdk_cert" ]]; then
        generate_sdk_cert
    elif [[ "${sub_command}" == "generate_sdk_csr" ]]; then
        generate_sdk_csr
    elif [[ "${sub_command}" == "sign_sdk_csr" ]]; then
        sign_sdk_csr
    elif [[ "${sub_command}" == "generate_private_key" ]]; then
        if [[ -z ${ip_params} ]];then
            generate_node_private_key
        else
            generate_multi_nodes_private_key
        fi
    elif [[ "${sub_command}" == "get_hsm_nodeid" ]]; then
        if [[ -z ${sub_cmd_param} ]]; then
            LOG_FALT "hsm pem file path param is empty, please use \'-p\' command to set hsm pem file path param."
        fi
        get_hsm_nodeid_from_pem_file
    elif [[ "${sub_command}" == "modify_multiple_ca_node" ]]; then
        modify_multiple_ca_node
    elif [[ "${sub_command}" == "generate_account" ]]; then
        generate_sdk_account
    elif [[ "${sub_command}" == "calc_account_address" ]]; then
        calculate_acccount_address
    else
        LOG_FALT "Unsupported command"
    fi
}

main "$@"
